using System;using UnityEngine;using UnityEngine.Experimental.Rendering;using UnityEngine.Animations;using UnityEngine.Playables;using UnityEngine.Rendering;
[DefaultExecutionOrder(2100)]public sealed class Eye206R2View:MonoBehaviour{
 public Eye204MotionView motion;public Renderer[]carriers;public ComputeShader compositor;public bool automaticPreview,context=true,playing;public float speed=.25f;public int frameIndex,frameIntervals=40;
 public Eye202View Layers=>motion.layers;public RenderTexture Reference{get;private set;}public RenderTexture Base{get;private set;}public RenderTexture Colour{get;private set;}public RenderTexture Owner{get;private set;}public RenderTexture Audit{get;private set;}
 PlayableGraph graph;AnimationClipPlayable playable;float elapsed;RenderPipelineAsset oldG,oldQ;float oldF,oldD,oldField,oldHide;bool switched;
 public float ClipSeconds=>motion.existingWalk.length*(frameIndex/(float)frameIntervals);
 public void SampleFrame(int index){frameIntervals=Mathf.RoundToInt(motion.existingWalk.length*motion.existingWalk.frameRate);if(frameIntervals<2||frameIntervals>120)throw new Exception("Unexpected source clip interval count; narrow scope required");frameIndex=Mathf.Clamp(index,0,frameIntervals);if(!graph.IsValid()){var a=motion.target;var c=motion.existingWalk;if(!a.avatar||!a.avatar.isValid||!a.avatar.isHuman||!c.humanMotion)throw new Exception("Existing humanoid inputs invalid");motion.Release();a.enabled=true;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;graph=PlayableGraph.Create("Eye206R2 existing one cycle only");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);playable=AnimationClipPlayable.Create(graph,c);playable.SetApplyFootIK(false);playable.SetApplyPlayableIK(false);playable.SetSpeed(0);var output=AnimationPlayableOutput.Create(graph,"Existing walk native-frame sample",a);output.SetSourcePlayable(playable);graph.Play();}playable.SetTime(ClipSeconds);graph.Evaluate(0);motion.currentLabel="Existing walk frame "+frameIndex+"/"+frameIntervals+" @ "+ClipSeconds.ToString("F5")+"s";Layers.game.actor.Apply();}
  RenderTexture Make(string n,bool floating){var r=new RenderTexture(new RenderTextureDescriptor(480,272){graphicsFormat=floating?GraphicsFormat.R32G32B32A32_SFloat:GraphicsFormat.R8G8B8A8_SRGB,depthBufferBits=0,enableRandomWrite=floating,msaaSamples=1}){name=n,filterMode=FilterMode.Point,wrapMode=TextureWrapMode.Clamp};r.Create();return r;}
 public void Render(bool env){if(!Reference){Reference=Make("206Reference",false);Base=Make("206Base",false);Colour=Make("206FinalLinear",true);Owner=Make("206Owner",true);Audit=Make("206Audit",true);}Layers.game.actor.Apply();Layers.RenderReference(env);Graphics.CopyTexture(Layers.game.Logical,Reference);Eye206R2Layers.Enabled=true;try{Layers.RenderBase(env,true);}finally{Eye206R2Layers.Enabled=false;}Graphics.CopyTexture(Layers.game.Logical,Base);
  int k=compositor.FindKernel("Compose");if(!compositor.IsSupported(k))throw new Exception("206 kernel unavailable");compositor.SetTexture(k,"_Reference",Reference);compositor.SetTexture(k,"_Base",Base);var s=Eye202Layers.Sets;compositor.SetTexture(k,"_FullMeta",s[9].meta.rt);compositor.SetTexture(k,"_BaseMeta",s[8].meta.rt);compositor.SetTexture(k,"_HairMeta",s[6].meta.rt);compositor.SetTexture(k,"_BrowMeta",s[7].meta.rt);compositor.SetTexture(k,"_LineMeta",s[4].meta.rt);compositor.SetTexture(k,"_HairRGBA",s[6].rgba.rt);compositor.SetTexture(k,"_BrowRGBA",s[7].rgba.rt);compositor.SetTexture(k,"_LineRGBA",s[4].rgba.rt);
  var a=Eye206R2Layers.Sets;foreach(var pair in new[]{("_W0",0),("_I0",1),("_W1",2),("_I1",3)}){compositor.SetTexture(k,pair.Item1,a[pair.Item2].rgba.rt);compositor.SetTexture(k,pair.Item1.Replace("0","M0").Replace("1","M1"),a[pair.Item2].meta.rt);}compositor.SetTexture(k,"_Colour",Colour);compositor.SetTexture(k,"_Owner",Owner);compositor.SetTexture(k,"_Audit",Audit);compositor.Dispatch(k,60,34,1);
 }

 void Start(){oldG=GraphicsSettings.defaultRenderPipeline;oldQ=QualitySettings.renderPipeline;oldF=Shader.GetGlobalFloat("_FHEnabled44");oldD=Shader.GetGlobalFloat("_E189Diag");oldField=Shader.GetGlobalFloat("_E189FieldEnabled");oldHide=Shader.GetGlobalFloat("_E202MainHideEyes");GraphicsSettings.defaultRenderPipeline=QualitySettings.renderPipeline=Layers.pipeline;Shader.SetGlobalFloat("_FHEnabled44",0);Shader.SetGlobalFloat("_E189Diag",0);Shader.SetGlobalFloat("_E189FieldEnabled",0);Shader.SetGlobalFloat("_E202MainHideEyes",0);Eye202Layers.Current=Layers;Eye206R2Layers.Current=this;switched=true;Layers.game.SetPose(0);Layers.game.Bind(true);SampleFrame(frameIndex);Eye206R2RenderStage.Install(this);}
 void Update(){if(!automaticPreview)return;if(playing){elapsed+=Time.unscaledDeltaTime*speed;float step=motion.existingWalk.length/frameIntervals;if(elapsed>=step){int n=Mathf.FloorToInt(elapsed/step);elapsed-=n*step;SampleFrame((frameIndex+n)%frameIntervals);}}}
 void LateUpdate(){}
 void OnGUI(){GUI.Label(new Rect(8,8,1150,42),"A206 technical fixture / "+motion.currentLabel+"\nGame130 reference: fixed PPU90.50967, camera30/yaw350, final480x272. Body3x + face8x from SAME frame; art HOLD.");if(GUI.Button(new Rect(15,58,75,25),playing?"Pause":"Play"))playing=!playing;if(GUI.Button(new Rect(98,58,70,25),"0.25x"))speed=.25f;if(GUI.Button(new Rect(176,58,60,25),"1x"))speed=1;if(GUI.Button(new Rect(244,58,50,25),"<")){playing=false;SampleFrame(Mathf.Max(0,frameIndex-1));}if(GUI.Button(new Rect(302,58,50,25),">")){playing=false;SampleFrame(Mathf.Min(frameIntervals,frameIndex+1));}if(GUI.Button(new Rect(360,58,80,25),"Frame0")){playing=false;SampleFrame(0);}if(Reference&&Colour){var body=new Rect(150/480f,(272-210)/272f,137/480f,156/272f);var face=new Rect(206/480f,(272-97)/272f,25/480f,24/272f);GUI.Label(new Rect(15,95,400,24),"Source baseline / body3x");GUI.Label(new Rect(460,95,400,24),"Attached authored eyes / body3x");GUI.DrawTextureWithTexCoords(new Rect(15,125,411,468),Reference,body,false);GUI.DrawTextureWithTexCoords(new Rect(460,125,411,468),Colour,body,false);GUI.Label(new Rect(15,608,400,20),"SAME frame: fixed face crop (206,73)-(231,97), 8x");GUI.DrawTextureWithTexCoords(new Rect(15,635,200,192),Reference,face,false);GUI.DrawTextureWithTexCoords(new Rect(460,635,200,192),Colour,face,false);}}
 void OnDisable(){Eye206R2RenderStage.Remove(this);if(graph.IsValid())graph.Destroy();Eye206R2Layers.Dispose();Eye202Layers.Dispose();foreach(var r in new[]{Reference,Base,Colour,Owner,Audit})if(r){r.Release();if(Application.isPlaying)Destroy(r);else DestroyImmediate(r);}Reference=Base=Colour=Owner=Audit=null;if(switched){GraphicsSettings.defaultRenderPipeline=oldG;QualitySettings.renderPipeline=oldQ;Shader.SetGlobalFloat("_FHEnabled44",oldF);Shader.SetGlobalFloat("_E189Diag",oldD);Shader.SetGlobalFloat("_E189FieldEnabled",oldField);Shader.SetGlobalFloat("_E202MainHideEyes",oldHide);switched=false;}}
}
